"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[139],{2329:(e,t,a)=>{a.d(t,{tS:()=>i,y$:()=>n});let n=[{name:"PAYMENT_INSTRUCTION",schema:"IPH",description:"One row per instant payment instruction received from any channel.",columns:[{name:"PAYMENT_ID",type:"VARCHAR2(30)",nullable:!1,description:"Primary key, IPH-P-<date>-<seq>."},{name:"END_TO_END_ID",type:"VARCHAR2(35)",nullable:!1,description:"Customer reference propagated to the scheme."},{name:"DEBTOR_IBAN",type:"VARCHAR2(34)",nullable:!1,description:"Account debited."},{name:"CREDITOR_IBAN",type:"VARCHAR2(34)",nullable:!1,description:"Beneficiary account."},{name:"CREDITOR_NAME",type:"VARCHAR2(70)",nullable:!1,description:"Beneficiary name as entered."},{name:"AMOUNT",type:"NUMBER(18,2)",nullable:!1,description:"Payment amount in EUR."},{name:"STATUS",type:"VARCHAR2(12)",nullable:!1,description:"Current payment state."},{name:"SCHEME_REFERENCE",type:"VARCHAR2(35)",nullable:!0,description:"TIPS reference assigned on settlement."},{name:"CREATED_AT",type:"TIMESTAMP(3)",nullable:!1,description:"Request intake timestamp."},{name:"SETTLED_AT",type:"TIMESTAMP(3)",nullable:!0,description:"Scheme settlement timestamp."}]},{name:"PAYMENT_CONTROL_RESULT",schema:"IPH",description:"Outcome of each in-path control (VoP, fraud, sanctions) with the rule and model versions applied.",columns:[{name:"CONTROL_ID",type:"VARCHAR2(30)",nullable:!1,description:"Primary key."},{name:"PAYMENT_ID",type:"VARCHAR2(30)",nullable:!1,description:"Foreign key to PAYMENT_INSTRUCTION."},{name:"CONTROL_TYPE",type:"VARCHAR2(20)",nullable:!1,description:"VOP | FRAUD | SANCTIONS."},{name:"RESULT",type:"VARCHAR2(20)",nullable:!1,description:"Control outcome."},{name:"SCORE",type:"NUMBER(3)",nullable:!0,description:"Numeric score where applicable."},{name:"RULE_VERSION",type:"VARCHAR2(12)",nullable:!1,description:"Version of the rule set or model."},{name:"LATENCY_MS",type:"NUMBER(6)",nullable:!1,description:"Control response time in milliseconds."}]},{name:"FUNDS_RESERVATION",schema:"IPH",description:"Two-phase ledger reservations and their release or conversion outcome.",columns:[{name:"RESERVATION_ID",type:"VARCHAR2(24)",nullable:!1,description:"Ledger reservation identifier."},{name:"PAYMENT_ID",type:"VARCHAR2(30)",nullable:!1,description:"Foreign key to PAYMENT_INSTRUCTION."},{name:"AMOUNT",type:"NUMBER(18,2)",nullable:!1,description:"Reserved amount."},{name:"STATE",type:"VARCHAR2(12)",nullable:!1,description:"HELD | CONVERTED | RELEASED | EXPIRED."},{name:"RESERVED_AT",type:"TIMESTAMP(3)",nullable:!1,description:"Reservation creation time."},{name:"RESOLVED_AT",type:"TIMESTAMP(3)",nullable:!0,description:"Conversion or release time."}]},{name:"SCHEME_SETTLEMENT",schema:"IPH",description:"Settlement lines parsed from the daily camt.053 statement received from TIPS.",columns:[{name:"SETTLEMENT_ID",type:"VARCHAR2(30)",nullable:!1,description:"Primary key."},{name:"SCHEME_REFERENCE",type:"VARCHAR2(35)",nullable:!1,description:"Scheme transaction reference."},{name:"AMOUNT",type:"NUMBER(18,2)",nullable:!1,description:"Settled amount."},{name:"DIRECTION",type:"VARCHAR2(3)",nullable:!1,description:"OUT | IN."},{name:"VALUE_DATE",type:"DATE",nullable:!1,description:"Settlement value date."}]}],i=[{id:"SQL-001",title:"Payments breaching the 10-second scheme deadline",purpose:"Evidence for REQ-020: confirm that no settled payment exceeded the scheme execution deadline during the UAT window.",database:"IPH_UAT (Oracle 19c)",status:"Validated",lastRun:"2025-05-15",executedBy:"Sofia Marchetti",sql:"-- REQ-020 / NFR evidence: end-to-end execution time distribution\nSELECT p.PAYMENT_ID,\n       p.END_TO_END_ID,\n       p.AMOUNT,\n       p.STATUS,\n       ROUND((CAST(p.SETTLED_AT AS DATE) - CAST(p.CREATED_AT AS DATE)) * 86400, 3) AS EXEC_SECONDS\n  FROM IPH.PAYMENT_INSTRUCTION p\n WHERE p.STATUS = 'ACCP'\n   AND p.CREATED_AT >= TIMESTAMP '2025-05-01 00:00:00'\n   AND (CAST(p.SETTLED_AT AS DATE) - CAST(p.CREATED_AT AS DATE)) * 86400 > 10\n ORDER BY EXEC_SECONDS DESC\n FETCH FIRST 20 ROWS ONLY;",columns:["PAYMENT_ID","END_TO_END_ID","AMOUNT","STATUS","EXEC_SECONDS"],rows:[],notes:["Zero rows returned across 41,882 settled UAT payments — the acceptance threshold is met.","The 95th percentile execution time measured separately was 4.62 seconds against a 5.00 second target.","Query re-run after the 12 May gateway patch with an identical result."],relatedRequirements:["REQ-020","REQ-006"],relatedRules:["BR-011"]},{id:"SQL-002",title:"Orphaned funds reservations",purpose:"Evidence for REQ-005 and BR-011: confirm that no reservation remains held beyond the 25-second expiry without a terminal payment state.",database:"IPH_UAT (Oracle 19c)",status:"Validated",lastRun:"2025-05-15",executedBy:"Priya Raghunathan",sql:"-- BR-011: reservations must never outlive the payment they secure\nSELECT r.RESERVATION_ID,\n       r.PAYMENT_ID,\n       r.AMOUNT,\n       r.STATE,\n       p.STATUS AS PAYMENT_STATUS,\n       ROUND((SYSTIMESTAMP - r.RESERVED_AT) * 86400) AS AGE_SECONDS\n  FROM IPH.FUNDS_RESERVATION r\n  JOIN IPH.PAYMENT_INSTRUCTION p\n    ON p.PAYMENT_ID = r.PAYMENT_ID\n WHERE r.STATE = 'HELD'\n   AND r.RESERVED_AT < SYSTIMESTAMP - INTERVAL '25' SECOND\n ORDER BY AGE_SECONDS DESC;",columns:["RESERVATION_ID","PAYMENT_ID","AMOUNT","STATE","PAYMENT_STATUS","AGE_SECONDS"],rows:[],notes:["Zero rows returned — the compensating release job is functioning as specified.","Two rows were returned on 08 May before defect DEF-1142 was fixed in build 2.3.4."],relatedRequirements:["REQ-005"],relatedRules:["BR-004","BR-011"]},{id:"SQL-003",title:"Payments exceeding the segment daily limit",purpose:"Evidence for BR-005: verify that no customer exceeded the rolling 24-hour cumulative limit for their segment.",database:"IPH_UAT (Oracle 19c)",status:"Validated",lastRun:"2025-05-14",executedBy:"Sofia Marchetti",sql:"-- BR-005: rolling 24h cumulative limit per customer segment\nWITH sent AS (\n  SELECT c.CUSTOMER_ID,\n         c.SEGMENT,\n         SUM(p.AMOUNT) AS SENT_24H\n    FROM IPH.PAYMENT_INSTRUCTION p\n    JOIN IPH.CUSTOMER_ACCOUNT c\n      ON c.IBAN = p.DEBTOR_IBAN\n   WHERE p.STATUS IN ('ACCP', 'PDNG')\n     AND p.CREATED_AT > SYSTIMESTAMP - INTERVAL '24' HOUR\n   GROUP BY c.CUSTOMER_ID, c.SEGMENT\n)\nSELECT s.CUSTOMER_ID,\n       s.SEGMENT,\n       s.SENT_24H,\n       l.DAILY_LIMIT\n  FROM sent s\n  JOIN IPH.SEGMENT_LIMIT l\n    ON l.SEGMENT = s.SEGMENT\n WHERE s.SENT_24H > l.DAILY_LIMIT\n ORDER BY s.SENT_24H DESC;",columns:["CUSTOMER_ID","SEGMENT","SENT_24H","DAILY_LIMIT"],rows:[],notes:["Zero breaches across the UAT population of 2,140 customers.","Cancelled and rejected payments are correctly excluded from the cumulative total."],relatedRequirements:["REQ-010"],relatedRules:["BR-005"]},{id:"SQL-004",title:"Control latency against the in-path budget",purpose:"Evidence for REQ-003 and REQ-004: confirm the fraud and sanctions controls respond within their allocated latency budgets.",database:"IPH_UAT (Oracle 19c)",status:"Needs Review",lastRun:"2025-05-16",executedBy:"Tobias Lindqvist",sql:"-- REQ-003 / REQ-004: in-path control latency profile\nSELECT c.CONTROL_TYPE,\n       COUNT(*)                                            AS EXECUTIONS,\n       ROUND(AVG(c.LATENCY_MS))                            AS AVG_MS,\n       ROUND(PERCENTILE_CONT(0.95)\n             WITHIN GROUP (ORDER BY c.LATENCY_MS))         AS P95_MS,\n       MAX(c.LATENCY_MS)                                   AS MAX_MS,\n       SUM(CASE WHEN c.CONTROL_TYPE = 'SANCTIONS'\n                 AND c.LATENCY_MS > 1200 THEN 1 ELSE 0 END) AS BUDGET_BREACHES\n  FROM IPH.PAYMENT_CONTROL_RESULT c\n WHERE c.CONTROL_TYPE IN ('FRAUD', 'SANCTIONS', 'VOP')\n GROUP BY c.CONTROL_TYPE\n ORDER BY P95_MS DESC;",columns:["CONTROL_TYPE","EXECUTIONS","AVG_MS","P95_MS","MAX_MS","BUDGET_BREACHES"],rows:[["VOP","41882","689","1412","1498","0"],["SANCTIONS","41882","574","1108","1974","38"],["FRAUD","41882","312","604","902","0"]],notes:["38 sanctions screening calls exceeded the 1,200 ms budget; all 38 correctly routed to manual review rather than auto-approving.","Breaches cluster between 12:00 and 12:04 CET, coinciding with the vendor list refresh window.","Raised as observation OBS-07 — vendor to move the list refresh outside peak hours before the next release."],relatedRequirements:["REQ-003","REQ-004","REQ-020"],relatedRules:["BR-008","BR-009"]},{id:"SQL-005",title:"Daily settlement reconciliation breaks",purpose:"Evidence for REQ-022: identify payments settled internally that are absent from, or mismatched against, the scheme statement.",database:"IPH_UAT (Oracle 19c)",status:"Validated",lastRun:"2025-05-16",executedBy:"Marcus Delacroix",sql:"-- REQ-022: reconcile internal settlements against camt.053\nSELECT p.PAYMENT_ID,\n       p.SCHEME_REFERENCE,\n       p.AMOUNT             AS INTERNAL_AMOUNT,\n       s.AMOUNT             AS SCHEME_AMOUNT,\n       CASE\n         WHEN s.SETTLEMENT_ID IS NULL           THEN 'MISSING_AT_SCHEME'\n         WHEN s.AMOUNT <> p.AMOUNT              THEN 'AMOUNT_MISMATCH'\n         ELSE 'MATCHED'\n       END                  AS BREAK_TYPE\n  FROM IPH.PAYMENT_INSTRUCTION p\n  LEFT JOIN IPH.SCHEME_SETTLEMENT s\n    ON s.SCHEME_REFERENCE = p.SCHEME_REFERENCE\n WHERE p.STATUS = 'ACCP'\n   AND TRUNC(p.SETTLED_AT) = DATE '2025-05-15'\n   AND (s.SETTLEMENT_ID IS NULL OR s.AMOUNT <> p.AMOUNT);",columns:["PAYMENT_ID","SCHEME_REFERENCE","INTERNAL_AMOUNT","SCHEME_AMOUNT","BREAK_TYPE"],rows:[["IPH-P-20250515-0041188","TIPS20250515X0044901","2400.00","—","MISSING_AT_SCHEME"]],notes:["One break raised and resolved the same banking day: a late pacs.002 accepted after the statement cut-off.","Break was correctly classified as LATE_CONFIRMATION by the reconciliation service and cleared on the 16 May statement."],relatedRequirements:["REQ-022","REQ-005"],relatedRules:["BR-016"]},{id:"SQL-006",title:"Duplicate end-to-end identification detection",purpose:"Evidence for BR-016: confirm that no duplicate end-to-end identification was accepted for the same debtor within 24 hours.",database:"IPH_UAT (Oracle 19c)",status:"Validated",lastRun:"2025-05-14",executedBy:"Sofia Marchetti",sql:"-- BR-016: duplicate detection on end-to-end identification\nSELECT p.DEBTOR_IBAN,\n       p.END_TO_END_ID,\n       COUNT(*)          AS OCCURRENCES,\n       MIN(p.CREATED_AT) AS FIRST_SEEN,\n       MAX(p.CREATED_AT) AS LAST_SEEN\n  FROM IPH.PAYMENT_INSTRUCTION p\n WHERE p.STATUS NOT IN ('RJCT', 'CANC')\n   AND p.CREATED_AT > SYSTIMESTAMP - INTERVAL '24' HOUR\n GROUP BY p.DEBTOR_IBAN, p.END_TO_END_ID\nHAVING COUNT(*) > 1;",columns:["DEBTOR_IBAN","END_TO_END_ID","OCCURRENCES","FIRST_SEEN","LAST_SEEN"],rows:[],notes:["Zero rows returned — idempotency handling correctly suppresses duplicate submissions.","Test TC-003 confirms that a repeated idempotency key returns the original payment rather than creating a second instruction."],relatedRequirements:["REQ-012","REQ-001"],relatedRules:["BR-016"]}]},3755:(e,t,a)=>{a.d(t,{DN:()=>i,kk:()=>n});let n=[{id:"BR-001",description:"An instant payment must not exceed the scheme maximum of EUR 100,000.00.",logic:"IF payment.amount > 100000.00 THEN reject WITH IPH-VAL-001 AND offer standard SCT fallback",priority:"Critical",source:"EPC SCT Inst Rulebook 2024 v1.1 \xa72.4",status:"Implemented",category:"Limits",owner:"Saadaoui Abdessalem",effectiveFrom:"2025-06-02",impactedRequirements:["REQ-001","REQ-011","REQ-016"]},{id:"BR-002",description:"Instant payments are permitted in EUR only.",logic:"IF payment.currency <> 'EUR' THEN reject WITH IPH-VAL-002",priority:"Critical",source:"EPC SCT Inst Rulebook 2024 v1.1 \xa72.2",status:"Implemented",category:"Validation",owner:"Saadaoui Abdessalem",effectiveFrom:"2025-06-02",impactedRequirements:["REQ-001","REQ-011"]},{id:"BR-003",description:"The debtor account must be open, in an active status, and free of debit blocks or legal holds.",logic:"IF account.status <> 'ACTIVE' OR account.blocks CONTAINS ('DEBIT','LEGAL','DECEASED') THEN reject WITH IPH-ACC-004",priority:"Critical",source:"Account Servicing Policy AS-11",status:"Implemented",category:"Account",owner:"Priya Raghunathan",effectiveFrom:"2025-06-02",impactedRequirements:["REQ-001","REQ-005"]},{id:"BR-004",description:"The available balance, including any agreed overdraft facility, must cover the full payment amount. Partial execution is not permitted.",logic:"available := ledger.balance - holds + overdraft.agreedLimit; IF available < payment.amount THEN reject WITH IPH-FND-007",priority:"Critical",source:"Credit Risk Policy CR-04",status:"Implemented",category:"Funds",owner:"Priya Raghunathan",effectiveFrom:"2025-06-02",impactedRequirements:["REQ-001","REQ-005"]},{id:"BR-005",description:"Rolling 24-hour cumulative instant payment limits apply per customer segment: Retail EUR 15,000, Retail Plus EUR 30,000, SME EUR 75,000.",logic:"sent24h := SUM(payments WHERE status IN ('ACCP','PDNG') AND createdAt > NOW()-24h); IF sent24h + payment.amount > segment.dailyLimit THEN reject WITH IPH-LIM-002",priority:"High",source:"Fraud Risk Appetite Statement FR-2025-03",status:"Implemented",category:"Limits",owner:"Tobias Lindqvist",effectiveFrom:"2025-06-02",impactedRequirements:["REQ-010","REQ-024"]},{id:"BR-006",description:"A Verification of Payee CLOSE_MATCH requires the customer to explicitly confirm or amend the beneficiary name before submission.",logic:"IF vop.result = 'CLOSE_MATCH' THEN require customerConfirmation = TRUE ELSE block submission WITH IPH-VOP-021",priority:"High",source:"EU Instant Payments Regulation (EU) 2024/886 Art. 5c",status:"Implemented",category:"Verification",owner:"Hannah Okafor",effectiveFrom:"2025-06-02",impactedRequirements:["REQ-002"]},{id:"BR-007",description:"A Verification of Payee NO_MATCH blocks straight-through submission for a beneficiary used for the first time.",logic:"IF vop.result = 'NO_MATCH' AND beneficiary.firstUse = TRUE THEN block WITH IPH-VOP-022 AND display scam warning",priority:"High",source:"Fraud Risk Appetite Statement FR-2025-03",status:"Implemented",category:"Verification",owner:"Tobias Lindqvist",effectiveFrom:"2025-06-02",impactedRequirements:["REQ-002","REQ-018"]},{id:"BR-008",description:"A confirmed sanctions match places the payment in a compliance hold; funds remain reserved and no partial release is permitted.",logic:"IF screening.result = 'HIT' THEN status := 'HELD_COMPLIANCE' AND retain reservation AND raise alert AND suppress tip-off messaging",priority:"Critical",source:"EU Funds Transfer Regulation 2015/847",status:"Implemented",category:"Compliance",owner:"Tobias Lindqvist",effectiveFrom:"2025-06-02",impactedRequirements:["REQ-003","REQ-008","REQ-023"]},{id:"BR-009",description:"Fraud score bands determine the outcome: 0–59 allow, 60–84 step-up authentication, 85–100 block and refer.",logic:"IF score >= 85 THEN block WITH IPH-FRD-031 ELSE IF score >= 60 THEN require stepUpAuthentication ELSE allow",priority:"High",source:"Fraud Decision Model IPH-ARIC v4.2",status:"Implemented",category:"Fraud",owner:"Tobias Lindqvist",effectiveFrom:"2025-06-02",impactedRequirements:["REQ-004"]},{id:"BR-010",description:"The first payment to a beneficiary registered less than 24 hours ago and above EUR 5,000 is held for 30 minutes and is cancellable by the customer.",logic:"IF beneficiary.ageHours < 24 AND payment.amount > 5000 THEN status := 'COOLING_OFF' FOR 30 MINUTES",priority:"High",source:"Fraud Risk Appetite Statement FR-2025-03",status:"Implemented",category:"Fraud",owner:"Tobias Lindqvist",effectiveFrom:"2025-06-02",impactedRequirements:["REQ-004","REQ-018"]},{id:"BR-011",description:"A funds reservation must be released automatically if no scheme confirmation is received within 25 seconds.",logic:"IF reservation.age > 25s AND scheme.response IS NULL THEN release reservation AND status := 'RJCT' WITH reason 'TIMEOUT'",priority:"Critical",source:"Functional Specification FS-004 \xa73.2",status:"Implemented",category:"Settlement",owner:"Priya Raghunathan",effectiveFrom:"2025-06-02",impactedRequirements:["REQ-005","REQ-006","REQ-007"]},{id:"BR-012",description:"If the beneficiary institution is not present in the daily TIPS reachability directory, the instant rail must not be used.",logic:"IF reachability.lookup(creditorBIC) = FALSE THEN reject WITH IPH-RCH-009 AND offer standard SCT fallback",priority:"High",source:"TIPS Participant Directory (daily)",status:"Implemented",category:"Routing",owner:"Saadaoui Abdessalem",effectiveFrom:"2025-06-02",impactedRequirements:["REQ-007","REQ-009","REQ-016"]},{id:"BR-013",description:"A recall may only be raised within 10 banking days of settlement and only with reason codes DUPL, TECH or FRAD.",logic:"IF bankingDaysSince(settlement) > 10 OR reasonCode NOT IN ('DUPL','TECH','FRAD') THEN reject WITH IPH-RCL-003",priority:"High",source:"EPC SCT Inst Rulebook 2024 v1.1 \xa74.3",status:"Implemented",category:"Exceptions",owner:"Marcus Delacroix",effectiveFrom:"2025-06-02",impactedRequirements:["REQ-013","REQ-014"]},{id:"BR-014",description:"Inbound instant payments are credited with immediate availability; value-dating or deferred availability is not permitted.",logic:"credit.valueDate := settlementTimestamp AND credit.availability := 'IMMEDIATE'",priority:"Critical",source:"EPC SCT Inst Rulebook 2024 v1.1 \xa73.1",status:"Implemented",category:"Settlement",owner:"Priya Raghunathan",effectiveFrom:"2025-06-02",impactedRequirements:["REQ-008","REQ-015"]},{id:"BR-015",description:"The low-value SCA exemption applies below EUR 500 provided the cumulative exempted amount since the last SCA does not exceed EUR 1,000 and no more than five consecutive exemptions have been used.",logic:"IF amount < 500 AND cumulativeExempt + amount <= 1000 AND consecutiveExemptions < 5 THEN exemptSca ELSE require SCA",priority:"High",source:"PSD2 RTS on SCA Art. 16",status:"Implemented",category:"Security",owner:"Tobias Lindqvist",effectiveFrom:"2025-06-02",impactedRequirements:["REQ-017"]},{id:"BR-016",description:"A payment whose end-to-end identification has already been used by the same debtor within 24 hours is treated as a duplicate.",logic:"IF EXISTS(payment WHERE endToEndId = request.endToEndId AND debtorAccount = request.debtorAccount AND createdAt > NOW()-24h) THEN reject WITH IPH-DUP-011",priority:"Medium",source:"Payments Operations Standard OPS-19",status:"Approved",category:"Validation",owner:"Marcus Delacroix",effectiveFrom:"2025-06-02",impactedRequirements:["REQ-012","REQ-021","REQ-022"]}],i=Array.from(new Set(n.map(e=>e.category))).sort()},6101:(e,t,a)=>{a.d(t,{Ov:()=>i,d$:()=>n});let n=[{id:"UML-001",title:"Instant Payment — Use Case Model",type:"Use Case",description:"Actors and use cases in scope for release 2.3, including the servicing and back-office capabilities introduced alongside the customer journey.",version:"2.3",author:"Saadaoui Abdessalem",lastUpdated:"2025-04-30",relatedRequirements:["REQ-001","REQ-010","REQ-012","REQ-013"],source:'@startuml IPH-UseCase\nleft to right direction\nskinparam packageStyle rectangle\n\nactor "Retail Customer" as RC\nactor "SME Customer" as SC\nactor "Contact Centre Agent" as CCA\nactor "Payments Ops Officer" as POO\nactor "Compliance Officer" as CO\nactor "TIPS Scheme" as TIPS\n\nrectangle "Instant Payments Hub" {\n  usecase "Initiate Instant Payment" as UC1\n  usecase "Verify Payee" as UC2\n  usecase "Check Payment Status" as UC3\n  usecase "Manage Payment Limits" as UC4\n  usecase "Raise Recall Request" as UC5\n  usecase "Adjudicate Compliance Hold" as UC6\n  usecase "Reconcile Settlement" as UC7\n  usecase "Receive Inbound Payment" as UC8\n}\n\nRC --\x3e UC1\nRC --\x3e UC3\nRC --\x3e UC4\nSC --\x3e UC1\nSC --\x3e UC3\nCCA --\x3e UC3\nCCA --\x3e UC5\nPOO --\x3e UC5\nPOO --\x3e UC7\nCO  --\x3e UC6\nTIPS --\x3e UC8\n\nUC1 ..> UC2 : <<include>>\nUC1 ..> UC6 : <<extend>>\nUC5 ..> UC7 : <<include>>\n@enduml'},{id:"UML-002",title:"Outbound Payment — Sequence Diagram",type:"Sequence",description:"Synchronous interaction between the channel, the hub, the financial crime services, the core ledger and the TIPS gateway, annotated with the stage latency budgets.",version:"2.3",author:"Priya Raghunathan",lastUpdated:"2025-05-14",relatedRequirements:["REQ-001","REQ-003","REQ-005","REQ-006"],source:'@startuml IPH-Sequence\nautonumber\nparticipant "Mobile App" as APP\nparticipant "Instant Payments Hub" as IPH\nparticipant "VoP Service" as VOP\nparticipant "Fraud Engine" as FRD\nparticipant "Sanctions Screening" as SAN\nparticipant "Core Ledger (T24)" as LDG\nparticipant "TIPS Gateway" as TIPS\n\nAPP -> IPH : POST /payments (pain-like request)\nactivate IPH\nIPH -> IPH : validate structure (300 ms)\nIPH -> VOP : verifyPayee(iban, name)\nVOP --\x3e IPH : CLOSE_MATCH (1,500 ms budget)\nIPH --\x3e APP : confirmation required\nAPP -> IPH : customer confirmed\nIPH -> FRD : score(paymentContext)\nFRD --\x3e IPH : score = 41 (800 ms)\nIPH -> SAN : screen(parties)\nSAN --\x3e IPH : CLEAR (1,200 ms)\nIPH -> LDG : reserveFunds(amount, ttl=25s)\nLDG --\x3e IPH : reservationId\nIPH -> TIPS : pacs.008\nTIPS --\x3e IPH : pacs.002 ACCP (4,000 ms budget)\nIPH -> LDG : convertReservation(reservationId)\nLDG --\x3e IPH : postingReference\nIPH --\x3e APP : 201 ACCP + schemeReference\ndeactivate IPH\n@enduml'},{id:"UML-003",title:"Instant Payments Hub — Component Diagram",type:"Component",description:"Logical component decomposition of the hub and its integration points with internal platforms and external scheme infrastructure.",version:"2.2",author:"Priya Raghunathan",lastUpdated:"2025-03-27",relatedRequirements:["REQ-006","REQ-019","REQ-022"],source:'@startuml IPH-Component\nskinparam componentStyle rectangle\n\npackage "Digital Channels" {\n  [Mobile Banking App]\n  [Internet Banking Portal]\n}\n\npackage "Instant Payments Hub" {\n  [Payment API Gateway]\n  [Orchestration Engine]\n  [Validation Service]\n  [Limit Service]\n  [Scheme Adapter]\n  [Reconciliation Service]\n  database "Payment Store" as PS\n}\n\npackage "Financial Crime" {\n  [Fraud Decision Engine]\n  [Sanctions Screening]\n}\n\npackage "Core Platforms" {\n  [Core Banking T24]\n  [Notification Service]\n  [Audit Store]\n}\n\ncloud "TIPS / ESMIG" as TIPS\n\n[Mobile Banking App] --\x3e [Payment API Gateway] : HTTPS / OAuth2\n[Internet Banking Portal] --\x3e [Payment API Gateway] : HTTPS / OAuth2\n[Payment API Gateway] --\x3e [Orchestration Engine]\n[Orchestration Engine] --\x3e [Validation Service]\n[Orchestration Engine] --\x3e [Limit Service]\n[Orchestration Engine] --\x3e [Fraud Decision Engine] : REST\n[Orchestration Engine] --\x3e [Sanctions Screening] : REST\n[Orchestration Engine] --\x3e [Core Banking T24] : reservation API\n[Orchestration Engine] --\x3e [Scheme Adapter]\n[Scheme Adapter] --\x3e TIPS : ISO 20022\n[Orchestration Engine] --\x3e PS\n[Orchestration Engine] --\x3e [Audit Store] : append-only\n[Orchestration Engine] --\x3e [Notification Service] : events\n[Reconciliation Service] --\x3e PS\n[Reconciliation Service] --\x3e TIPS : camt.053\n@enduml'},{id:"UML-004",title:"Payment Validation — Activity Diagram",type:"Activity",description:"Decision logic applied between request intake and scheme submission, including the compensating release path.",version:"2.3",author:"Saadaoui Abdessalem",lastUpdated:"2025-05-06",relatedRequirements:["REQ-002","REQ-004","REQ-005","REQ-011"],source:"@startuml IPH-Activity\nstart\n:Receive payment request;\nif (Amount <= 100,000 EUR and currency = EUR?) then (no)\n  :Reject IPH-VAL-001;\n  :Offer standard SCT;\n  stop\nendif\n:Verify payee;\nif (VoP result?) then (NO_MATCH and first use)\n  :Block IPH-VOP-022;\n  stop\nelseif (CLOSE_MATCH) then\n  :Request customer confirmation;\nendif\n:Evaluate limits;\nif (Within 24h limit?) then (no)\n  :Reject IPH-LIM-002;\n  stop\nendif\n:Score fraud risk;\nif (Score >= 85?) then (yes)\n  :Block and create fraud case;\n  stop\nelseif (Score >= 60?) then (yes)\n  :Step-up authentication;\nendif\n:Screen sanctions;\nif (Hit?) then (yes)\n  :Hold for compliance review;\n  stop\nendif\n:Reserve funds;\n:Submit pacs.008;\nif (pacs.002 ACCP within 10s?) then (yes)\n  :Convert reservation to debit;\n  :Notify customer;\n  stop\nelse (no)\n  :Release reservation;\n  :Reject with scheme reason;\n  stop\nendif\n@enduml"},{id:"UML-005",title:"Payment Lifecycle — State Machine",type:"State",description:"Permitted payment states and transitions. Terminal states are immutable; late scheme messages create linked exception records.",version:"2.3",author:"Priya Raghunathan",lastUpdated:"2025-05-14",relatedRequirements:["REQ-007","REQ-012","REQ-013"],source:"@startuml IPH-State\n[*] --\x3e RCVD : request accepted\nRCVD --\x3e VALD : structural validation passed\nRCVD --\x3e RJCT : validation failed\nVALD --\x3e COOLING_OFF : first-use beneficiary > 5,000 EUR\nCOOLING_OFF --\x3e SCRN : 30 minutes elapsed\nCOOLING_OFF --\x3e CANC : customer cancelled\nVALD --\x3e SCRN : controls invoked\nSCRN --\x3e HELD : sanctions hit\nSCRN --\x3e RJCT : fraud block\nSCRN --\x3e RSVD : controls cleared\nRSVD --\x3e SUBM : pacs.008 submitted\nSUBM --\x3e ACCP : pacs.002 ACCP\nSUBM --\x3e RJCT : pacs.002 RJCT or timeout\nHELD --\x3e ACCP : compliance released\nHELD --\x3e RJCT : compliance rejected\nACCP --\x3e RECALLED : recall accepted by beneficiary bank\nACCP --\x3e [*]\nRJCT --\x3e [*]\nCANC --\x3e [*]\nRECALLED --\x3e [*]\n@enduml"}],i=[{id:"WF-001",title:"Instant Payment — Amount & Beneficiary",screenId:"SCR-PAY-01",description:"Primary capture screen for a new instant payment. Presents the instant badge, the remaining daily allowance and inline IBAN validation.",channel:"Mobile",version:"2.3",status:"Approved",author:"Hannah Okafor",lastUpdated:"2025-03-19",annotations:["The instant badge is shown only once beneficiary reachability has been confirmed.","The remaining daily allowance is refreshed on every screen entry.","IBAN validation is inline and non-blocking until the field loses focus."],relatedRequirements:["REQ-001","REQ-009","REQ-010"]},{id:"WF-002",title:"Verification of Payee — Close Match",screenId:"SCR-PAY-02",description:"Interstitial presented when the beneficiary name is a close match, showing the registered name and requiring an explicit customer decision.",channel:"Mobile",version:"2.3",status:"Approved",author:"Hannah Okafor",lastUpdated:"2025-04-02",annotations:["The registered name is displayed exactly as held by the beneficiary bank.","Continue is a secondary action; Amend details is the visually primary action.","The customer decision is written to the audit trail with the match score."],relatedRequirements:["REQ-002"]},{id:"WF-003",title:"Payment Confirmation & SCA Challenge",screenId:"SCR-PAY-03",description:"Review and authorise screen with dynamic linking: the challenge repeats the exact amount and beneficiary name.",channel:"Mobile",version:"2.3",status:"Approved",author:"Hannah Okafor",lastUpdated:"2025-03-26",annotations:["Amount and payee are restated inside the biometric prompt to satisfy dynamic linking.","Any amendment invalidates the challenge and issues a new one.","Exempted payments show an explanatory note in place of the challenge."],relatedRequirements:["REQ-017"]},{id:"WF-004",title:"Payment Result — Settled",screenId:"SCR-PAY-04",description:"Success state showing the scheme reference, the settlement timestamp and the updated available balance.",channel:"Mobile",version:"2.3",status:"Approved",author:"Hannah Okafor",lastUpdated:"2025-03-26",annotations:["The scheme reference is copyable for customer records.","Share receipt generates a PDF confirmation."],relatedRequirements:["REQ-001","REQ-015"]},{id:"WF-005",title:"Payment Result — Rejected with Fallback",screenId:"SCR-PAY-05",description:"Failure state presenting the translated scheme reason and a single-tap fallback to a standard SEPA credit transfer.",channel:"Mobile",version:"2.2",status:"Approved",author:"Hannah Okafor",lastUpdated:"2025-04-09",annotations:["Scheme reason codes are never shown raw; the mapping table supplies plain-language text.","The fallback retains all captured details and states the next value date."],relatedRequirements:["REQ-007","REQ-016"]},{id:"WF-006",title:"Operations Console — Exception Queues",screenId:"SCR-OPS-01",description:"Back-office triage workspace listing compliance holds, fraud reviews, failed reservations and reconciliation breaks with four-eyes release.",channel:"Back Office",version:"1.0",status:"In Review",author:"Marcus Delacroix",lastUpdated:"2025-09-08",annotations:["Queue counts refresh every 30 seconds without a full page reload.","Release requires a second authoriser; the action is disabled for the initiator.","Every action writes to the immutable audit trail with a business justification."],relatedRequirements:["REQ-023","REQ-003"]}]},8995:(e,t,a)=>{a.d(t,{Cj:()=>i,Gc:()=>s,Ln:()=>n});let n=[{id:"REQ-001",title:"Initiate SEPA Instant Credit Transfer from digital channels",businessNeed:"Retail and SME customers expect euro payments to reach the beneficiary immediately, at any hour. The legacy batch engine only executes four times per business day, driving complaints and attrition to challenger banks.",description:"The Instant Payments Hub must accept a payment initiation request from the web and mobile banking channels and execute it as an SCT Inst transaction. The request captures debtor account, creditor IBAN and name, amount in EUR, and an optional remittance reference of up to 140 characters. The hub orchestrates validation, screening, funds reservation and scheme submission synchronously and returns a final status to the channel.",priority:"Critical",status:"Implemented",category:"Payment Initiation",moscow:"Must",owner:"Saadaoui Abdessalem",lastUpdated:"2025-05-16",version:"2.3",acceptanceCriteria:[{id:"AC-001-1",given:"an authenticated retail customer with an active current account",when:"they submit a valid instant payment of EUR 250.00 to a reachable IBAN",then:"the payment is settled and a final ACCP status with the scheme transaction reference is returned within 10 seconds"},{id:"AC-001-2",given:"a payment request with a remittance reference exceeding 140 characters",when:"the channel submits the request",then:"the hub rejects it with error code IPH-VAL-014 and no funds are reserved"}],relatedDocuments:["DOC-001","DOC-002"],relatedApis:["API-001"],relatedTestCases:["TC-001","TC-002","TC-003"],relatedRules:["BR-001","BR-002","BR-003","BR-004"]},{id:"REQ-002",title:"Verification of Payee before payment submission",businessNeed:"The EU Instant Payments Regulation mandates a payee verification service. Misdirected and APP-fraud payments cost the bank EUR 2.4m in the previous financial year.",description:"Before a payment is submitted to the scheme, the hub must call the Verification of Payee service to compare the creditor name supplied by the customer against the name registered at the beneficiary bank. The service returns MATCH, CLOSE_MATCH (with the registered name) or NO_MATCH. The channel must present the outcome to the customer and require an explicit confirmation for anything other than MATCH.",priority:"Critical",status:"Implemented",category:"Validation & Screening",moscow:"Must",owner:"Hannah Okafor",lastUpdated:"2025-04-30",version:"2.3",acceptanceCriteria:[{id:"AC-002-1",given:"a creditor name that differs only by a middle initial from the registered name",when:"Verification of Payee is invoked",then:"a CLOSE_MATCH is returned with the registered name and the customer is asked to confirm or amend"},{id:"AC-002-2",given:"the Verification of Payee service is unavailable",when:"the customer submits a payment",then:"the customer is warned that verification could not be performed and must accept the risk before submission"}],relatedDocuments:["DOC-001","DOC-003"],relatedApis:["API-004"],relatedTestCases:["TC-004","TC-005","TC-006"],relatedRules:["BR-006","BR-007"]},{id:"REQ-003",title:"Real-time sanctions screening within the payment path",businessNeed:"Funds Transfer Regulation 2015/847 requires screening of all payment parties before execution. Irrevocable instant settlement removes any opportunity for post-execution intervention.",description:"Every outbound and inbound instant payment must be screened against consolidated sanctions and watch lists before settlement. Screening is synchronous with a hard response budget of 1,200 ms. A confirmed hit places the payment in a compliance hold queue and the customer receives a neutral 'under review' message that does not tip off the subject.",priority:"Critical",status:"Implemented",category:"Validation & Screening",moscow:"Must",owner:"Tobias Lindqvist",lastUpdated:"2025-05-02",version:"2.3",acceptanceCriteria:[{id:"AC-003-1",given:"a creditor name matching an EU consolidated list entry",when:"the payment is screened",then:"the payment is held, no funds leave the account, and a compliance alert is raised within 5 seconds"},{id:"AC-003-2",given:"the screening platform does not respond within 1,200 ms",when:"the circuit breaker threshold is reached",then:"the payment is routed to the manual review queue rather than being auto-approved"}],relatedDocuments:["DOC-003","DOC-005"],relatedApis:["API-001"],relatedTestCases:["TC-007","TC-008"],relatedRules:["BR-008"]},{id:"REQ-004",title:"Real-time fraud scoring and decisioning",businessNeed:"Instant, irrevocable payments materially increase authorised push payment fraud exposure. The bank must intervene before settlement, not after.",description:"Each outbound payment must be scored by the behavioural fraud engine using customer history, device signals, beneficiary novelty and velocity. The returned score (0–100) drives an automated decision: allow, step-up authentication, or block with referral to the fraud operations team.",priority:"High",status:"Implemented",category:"Validation & Screening",moscow:"Must",owner:"Tobias Lindqvist",lastUpdated:"2025-04-18",version:"2.3",acceptanceCriteria:[{id:"AC-004-1",given:"a payment scored at 72 by the fraud engine",when:"the decision rules are evaluated",then:"the customer is challenged with step-up authentication before the payment continues"},{id:"AC-004-2",given:"a payment scored at 91",when:"the decision rules are evaluated",then:"the payment is blocked, a fraud case is created and the customer is directed to the fraud contact number"}],relatedDocuments:["DOC-003"],relatedApis:["API-001"],relatedTestCases:["TC-009","TC-010","TC-011"],relatedRules:["BR-009","BR-010"]},{id:"REQ-005",title:"Two-phase funds reservation on the core ledger",businessNeed:"Funds must be guaranteed before scheme submission, but must never be trapped if the scheme rejects or times out.",description:"The hub reserves the payment amount on the debtor account before submitting to TIPS. On a positive scheme confirmation the reservation is converted to a booked debit. On rejection, timeout or any downstream failure the reservation is released automatically. A compensating job releases orphaned reservations older than 60 seconds.",priority:"Critical",status:"Implemented",category:"Settlement",moscow:"Must",owner:"Priya Raghunathan",lastUpdated:"2025-03-28",version:"2.3",acceptanceCriteria:[{id:"AC-005-1",given:"an accepted scheme confirmation",when:"the hub receives the ACCP status",then:"the reservation is converted to a booked debit with the scheme reference in the ledger narrative"},{id:"AC-005-2",given:"no scheme response within 25 seconds",when:"the reservation timer expires",then:"the reservation is released and the available balance is restored"}],relatedDocuments:["DOC-002","DOC-004"],relatedApis:["API-001"],relatedTestCases:["TC-012","TC-013"],relatedRules:["BR-004","BR-011"]},{id:"REQ-006",title:"Submit payment to TIPS within the scheme deadline",businessNeed:"The SCT Inst rulebook requires the originating bank to complete the end-to-end flow within 10 seconds or abandon the transaction.",description:"The hub must construct a pacs.008 ISO 20022 message and submit it to the TIPS gateway, correlating the pacs.002 response by end-to-end identification. The overall time budget is allocated as: validation 300 ms, VoP 1,500 ms, screening 1,200 ms, fraud 800 ms, reservation 400 ms, scheme round trip 4,000 ms.",priority:"Critical",status:"Implemented",category:"Settlement",moscow:"Must",owner:"Priya Raghunathan",lastUpdated:"2025-03-14",version:"2.3",acceptanceCriteria:[{id:"AC-006-1",given:"a validated and funded payment",when:"the pacs.008 is submitted",then:"a pacs.002 response is correlated and persisted against the payment within the 10-second budget"}],relatedDocuments:["DOC-002","DOC-004"],relatedApis:["API-001"],relatedTestCases:["TC-014","TC-015"],relatedRules:["BR-011"]},{id:"REQ-007",title:"Handle scheme timeout and negative confirmation",businessNeed:"Ambiguous payment outcomes are the largest driver of duplicate payments and customer complaints in real-time schemes.",description:"Where TIPS returns a negative pacs.002 or no response within the deadline, the hub must set the payment to a deterministic terminal state, release the reservation, present a clear channel message with the scheme reason code translated to plain language, and offer the customer a retry or a standard SCT fallback.",priority:"High",status:"Implemented",category:"Recall & Exceptions",moscow:"Must",owner:"Saadaoui Abdessalem",lastUpdated:"2025-04-11",version:"2.3",acceptanceCriteria:[{id:"AC-007-1",given:"a pacs.002 with reason code AC04 (closed account)",when:"the response is processed",then:"the payment status becomes RJCT, funds are released, and the customer sees 'The beneficiary account is closed'"}],relatedDocuments:["DOC-002"],relatedApis:["API-001","API-002"],relatedTestCases:["TC-016","TC-017"],relatedRules:["BR-011","BR-012"]},{id:"REQ-008",title:"Receive and credit inbound instant payments",businessNeed:"Scheme reachability requires the bank to accept inbound SCT Inst payments 24/7 and credit the beneficiary immediately.",description:"The hub must accept inbound pacs.008 messages from TIPS, validate the creditor account, screen the parties, credit the account with immediate value and return a pacs.002 acceptance within 5 seconds. Rejections must use the correct scheme reason codes.",priority:"Critical",status:"Implemented",category:"Settlement",moscow:"Must",owner:"Priya Raghunathan",lastUpdated:"2025-04-25",version:"2.3",acceptanceCriteria:[{id:"AC-008-1",given:"an inbound payment to an active current account",when:"the message is validated and screened clean",then:"the account is credited with immediate availability and a positive pacs.002 is returned"},{id:"AC-008-2",given:"an inbound payment to a closed account",when:"the message is validated",then:"a negative pacs.002 with reason code AC04 is returned and no credit is posted"}],relatedDocuments:["DOC-002","DOC-004"],relatedApis:["API-001"],relatedTestCases:["TC-018","TC-019","TC-020"],relatedRules:["BR-014","BR-008"]},{id:"REQ-009",title:"Beneficiary bank reachability check",businessNeed:"Not all SEPA banks are reachable for instant payments. Attempting an unreachable payment wastes the customer's time and creates avoidable rejections.",description:"Before initiating, the hub must check the beneficiary BIC against the daily TIPS reachability directory. Unreachable institutions must be identified in the channel before the customer confirms, with an automatic offer to send the payment as a standard SCT instead.",priority:"High",status:"Implemented",category:"Validation & Screening",moscow:"Must",owner:"Saadaoui Abdessalem",lastUpdated:"2025-02-19",version:"2.3",acceptanceCriteria:[{id:"AC-009-1",given:"a beneficiary BIC absent from the reachability directory",when:"the customer enters the IBAN",then:"the channel displays that instant payment is unavailable and offers standard SCT with the next value date"}],relatedDocuments:["DOC-001"],relatedApis:["API-004"],relatedTestCases:["TC-021","TC-022"],relatedRules:["BR-012"]},{id:"REQ-010",title:"Customer instant payment limits",businessNeed:"The bank must contain fraud exposure per customer while allowing genuine high-value payments through a controlled uplift path.",description:"Configurable per-transaction and rolling 24-hour cumulative limits apply per customer segment. Customers may view their limits and remaining allowance in the channel, and may request a temporary uplift subject to step-up authentication and a fraud review.",priority:"High",status:"Implemented",category:"Limits & Controls",moscow:"Must",owner:"Hannah Okafor",lastUpdated:"2025-04-07",version:"2.3",acceptanceCriteria:[{id:"AC-010-1",given:"a retail customer with a EUR 15,000 daily limit who has already sent EUR 14,500",when:"they attempt a further payment of EUR 800",then:"the payment is rejected with IPH-LIM-002 and the remaining allowance of EUR 500 is displayed"}],relatedDocuments:["DOC-001","DOC-006"],relatedApis:["API-005"],relatedTestCases:["TC-023","TC-024"],relatedRules:["BR-005"]},{id:"REQ-011",title:"Enforce the EUR 100,000 scheme cap",businessNeed:"Payments above the scheme maximum are rejected by TIPS and must never be submitted.",description:"The hub must reject any instant payment request with an amount greater than EUR 100,000.00 at the validation stage, before any downstream call, and present the standard SCT alternative in the channel.",priority:"Critical",status:"Implemented",category:"Limits & Controls",moscow:"Must",owner:"Saadaoui Abdessalem",lastUpdated:"2025-01-30",version:"2.3",acceptanceCriteria:[{id:"AC-011-1",given:"a payment request of EUR 100,000.01",when:"the request is validated",then:"it is rejected with IPH-VAL-001 within 300 ms and no downstream service is called"}],relatedDocuments:["DOC-001"],relatedApis:["API-001"],relatedTestCases:["TC-025","TC-026"],relatedRules:["BR-001","BR-002"]},{id:"REQ-012",title:"Payment status enquiry",businessNeed:"Contact centre agents and customers need an authoritative, real-time view of a payment's state to resolve queries at first contact.",description:"The hub must expose a status enquiry operation returning the current payment state, scheme reference, timestamps for each processing stage, and the translated reason code where applicable. Results are available to the channel, the contact centre desktop and the operations console.",priority:"Medium",status:"Implemented",category:"Servicing",moscow:"Must",owner:"Hannah Okafor",lastUpdated:"2025-04-22",version:"2.3",acceptanceCriteria:[{id:"AC-012-1",given:"a payment identifier for a settled payment",when:"the status enquiry is called",then:"the response contains status ACCP, the scheme reference and the settlement timestamp"}],relatedDocuments:["DOC-002"],relatedApis:["API-002"],relatedTestCases:["TC-027","TC-028"],relatedRules:["BR-016"]},{id:"REQ-013",title:"Raise an SCT Inst recall request",businessNeed:"Customers who send a payment in error, and fraud operations acting on a confirmed scam, need a scheme-compliant route to request the funds back.",description:"Authorised users must be able to raise a recall for a settled instant payment using a permitted scheme reason code (duplicate payment, technical problem, fraudulent origin). The hub generates the camt.056 message, tracks the beneficiary bank's response and updates the case accordingly.",priority:"High",status:"Implemented",category:"Recall & Exceptions",moscow:"Should",owner:"Marcus Delacroix",lastUpdated:"2025-05-09",version:"2.3",acceptanceCriteria:[{id:"AC-013-1",given:"a payment settled 3 banking days ago",when:"an operations user raises a recall with reason code FRAD",then:"a camt.056 is generated and the recall case is created with a 10-banking-day response clock"},{id:"AC-013-2",given:"a payment settled 12 banking days ago",when:"a recall is attempted",then:"the request is rejected with IPH-RCL-003 as the scheme window has closed"}],relatedDocuments:["DOC-002","DOC-005"],relatedApis:["API-003"],relatedTestCases:["TC-029","TC-030"],relatedRules:["BR-013"]},{id:"REQ-014",title:"Process inbound recall requests",businessNeed:"The scheme obliges the beneficiary bank to answer recall requests within 10 banking days; failure attracts scheme penalties.",description:"Inbound camt.056 messages must create a recall case, place a hold on the disputed amount where the funds remain available, notify the beneficiary customer where legally permitted, and generate the camt.029 response with the agreed or rejected outcome.",priority:"High",status:"Approved",category:"Recall & Exceptions",moscow:"Should",owner:"Marcus Delacroix",lastUpdated:"2025-05-09",version:"2.3",acceptanceCriteria:[{id:"AC-014-1",given:"an inbound recall where the full amount is still available",when:"the operations user approves the return",then:"a camt.029 acceptance is sent and the funds are returned within the same banking day"}],relatedDocuments:["DOC-005"],relatedApis:["API-003"],relatedTestCases:["TC-031","TC-032"],relatedRules:["BR-013"]},{id:"REQ-015",title:"Customer notification for instant credits and debits",businessNeed:"Immediate confirmation reduces contact centre volume and gives customers assurance that irrevocable funds have moved.",description:"The hub must publish notification events for settled outbound payments, received inbound payments and rejected payments. The notification service delivers push, in-app and optional SMS messages using the customer's contact preferences, with quiet-hours suppression for non-urgent messages.",priority:"Medium",status:"Implemented",category:"Servicing",moscow:"Must",owner:"Hannah Okafor",lastUpdated:"2025-05-13",version:"2.3",acceptanceCriteria:[{id:"AC-015-1",given:"a settled inbound payment of EUR 1,200",when:"the credit is posted",then:"a push notification is delivered within 30 seconds showing the amount, sender name and new balance"}],relatedDocuments:["DOC-001","DOC-006"],relatedApis:["API-002"],relatedTestCases:["TC-033","TC-034"],relatedRules:["BR-014"]},{id:"REQ-016",title:"Fallback to standard SCT when instant execution is unavailable",businessNeed:"Customers should always be able to complete their payment, even when the instant rail is unavailable or unsuitable.",description:"Where the beneficiary is unreachable, the amount exceeds the scheme cap, or the instant rail is degraded, the channel must offer a one-click fallback to a standard SEPA credit transfer with the applicable value date, without re-keying payment details.",priority:"Medium",status:"Implemented",category:"Payment Initiation",moscow:"Should",owner:"Hannah Okafor",lastUpdated:"2025-04-02",version:"2.3",acceptanceCriteria:[{id:"AC-016-1",given:"an unreachable beneficiary bank",when:"the customer accepts the fallback offer",then:"a standard SCT is created with the same details and the next available value date is confirmed"}],relatedDocuments:["DOC-001"],relatedApis:["API-001"],relatedTestCases:["TC-035"],relatedRules:["BR-012"]},{id:"REQ-017",title:"Strong Customer Authentication for payment initiation",businessNeed:"PSD2 requires SCA with dynamic linking for electronic payment transactions initiated by the payer.",description:"Payment initiation must be authenticated with two independent factors, and the authentication code must be dynamically linked to the amount and the payee. Permitted exemptions (trusted beneficiary, low value) must be applied consistently and logged for audit.",priority:"Critical",status:"Implemented",category:"Security & Compliance",moscow:"Must",owner:"Tobias Lindqvist",lastUpdated:"2025-03-06",version:"2.3",acceptanceCriteria:[{id:"AC-017-1",given:"an authenticated payment of EUR 4,000 to a new beneficiary",when:"the customer confirms",then:"SCA is requested and the challenge displays the exact amount and beneficiary name"},{id:"AC-017-2",given:"a EUR 40 payment to a registered trusted beneficiary",when:"the customer confirms",then:"the low-value exemption is applied, no challenge is raised, and the exemption is recorded in the audit log"}],relatedDocuments:["DOC-003","DOC-005"],relatedApis:["API-001"],relatedTestCases:["TC-036","TC-037"],relatedRules:["BR-015"]},{id:"REQ-018",title:"Cooling-off period for first-time beneficiaries",businessNeed:"Scam payments are concentrated in the first payment to a newly added beneficiary; a short delay materially reduces losses.",description:"The first payment to a newly registered beneficiary above EUR 5,000 is held for 30 minutes, during which the customer receives a scam-awareness message and may cancel without charge. Subsequent payments to the same beneficiary are unaffected.",priority:"High",status:"Implemented",category:"Limits & Controls",moscow:"Should",owner:"Tobias Lindqvist",lastUpdated:"2025-04-18",version:"2.3",acceptanceCriteria:[{id:"AC-018-1",given:"a EUR 7,500 payment to a beneficiary added 10 minutes ago",when:"the customer confirms the payment",then:"the payment is held for 30 minutes, is cancellable, and releases automatically on expiry"}],relatedDocuments:["DOC-003"],relatedApis:["API-001"],relatedTestCases:["TC-038"],relatedRules:["BR-010"]},{id:"REQ-019",title:"Continuous 24/7/365 availability",businessNeed:"Instant payment schemes have no batch window; unavailability directly breaches the scheme service level and attracts penalties.",description:"The hub must operate continuously with a monthly availability of at least 99.9% measured against inbound scheme traffic. Deployments must be zero-downtime, and any planned maintenance must be executed without suspending scheme reachability.",priority:"High",status:"Implemented",category:"Non-Functional",moscow:"Must",owner:"Priya Raghunathan",lastUpdated:"2025-05-20",version:"2.3",acceptanceCriteria:[{id:"AC-019-1",given:"a rolling application deployment",when:"inbound scheme traffic is received during the deployment",then:"all inbound payments are answered successfully with no scheme timeouts"}],relatedDocuments:["DOC-004"],relatedApis:[],relatedTestCases:["TC-039"],relatedRules:[]},{id:"REQ-020",title:"End-to-end processing within 10 seconds",businessNeed:"The SCT Inst rulebook defines a maximum execution time of 10 seconds end to end.",description:"95% of outbound payments must complete within 5 seconds and 99.9% within 10 seconds, measured from channel submission to final status. Stage-level timings must be captured and exposed to the operations dashboard for breach analysis.",priority:"Critical",status:"Implemented",category:"Non-Functional",moscow:"Must",owner:"Priya Raghunathan",lastUpdated:"2025-05-20",version:"2.3",acceptanceCriteria:[{id:"AC-020-1",given:"a sustained load of 120 transactions per second",when:"the performance test is executed for 60 minutes",then:"the 95th percentile response time remains at or below 5,000 ms"}],relatedDocuments:["DOC-004"],relatedApis:["API-001"],relatedTestCases:["TC-039"],relatedRules:[]},{id:"REQ-021",title:"Immutable payment audit trail",businessNeed:"Regulators and Internal Audit require a complete, tamper-evident record of every decision taken in the payment path.",description:"Every payment must produce an append-only audit record capturing the request payload, each validation outcome, screening and fraud decisions with the rule versions applied, the authorising user or exemption, and all scheme messages. Records are retained for 10 years and are searchable by payment reference, account and date range.",priority:"High",status:"Implemented",category:"Security & Compliance",moscow:"Must",owner:"Gerald Vance",lastUpdated:"2025-05-06",version:"2.3",acceptanceCriteria:[{id:"AC-021-1",given:"a payment blocked by the fraud engine",when:"the audit record is retrieved",then:"it contains the score, the model version, the rule identifier and the operator who reviewed the case"}],relatedDocuments:["DOC-005","DOC-007"],relatedApis:["API-002"],relatedTestCases:["TC-027"],relatedRules:["BR-016"]},{id:"REQ-022",title:"Daily reconciliation with the TIPS settlement report",businessNeed:"Unreconciled scheme positions create ledger breaks and regulatory reporting errors that must be identified same-day.",description:"Each business day the hub must reconcile internal payment records against the camt.053 settlement statement received from TIPS, classify any break by type, and publish an exception report to Payments Operations by 07:00 CET.",priority:"High",status:"Implemented",category:"Reporting & Operations",moscow:"Must",owner:"Marcus Delacroix",lastUpdated:"2025-04-29",version:"2.3",acceptanceCriteria:[{id:"AC-022-1",given:"a settled payment absent from the scheme statement",when:"reconciliation runs",then:"a break of type MISSING_AT_SCHEME is raised and included in the 07:00 exception report"}],relatedDocuments:["DOC-004","DOC-007"],relatedApis:[],relatedTestCases:["TC-028"],relatedRules:["BR-016"]},{id:"REQ-023",title:"Operations console and exception queues",businessNeed:"Payments Operations needs a single place to triage held, failed and unreconciled payments without direct database access.",description:"A role-based operations console must present the compliance hold queue, the fraud review queue, failed reservations and reconciliation breaks, with search, assignment, four-eyes release and full action history. All actions are written to the audit trail.",priority:"Medium",status:"In Review",category:"Reporting & Operations",moscow:"Should",owner:"Marcus Delacroix",lastUpdated:"2025-09-08",version:"2.4",acceptanceCriteria:[{id:"AC-023-1",given:"a payment in the compliance hold queue",when:"an authorised officer releases it",then:"a second authoriser is required before the payment resumes and both identities are recorded"}],relatedDocuments:["DOC-006"],relatedApis:["API-002"],relatedTestCases:[],relatedRules:["BR-008"]},{id:"REQ-024",title:"Bulk instant payments for SME customers",businessNeed:"SME customers running payroll want the certainty of instant settlement across a file of beneficiaries.",description:"Accept a payment file of up to 500 instant payments from the SME channel, validate and execute each item individually, and report per-item outcomes with a consolidated file status. Deferred from release 2.3 following the capacity assessment.",priority:"Low",status:"Draft",category:"Payment Initiation",moscow:"Could",owner:"Hannah Okafor",lastUpdated:"2025-05-28",version:"2.5",acceptanceCriteria:[{id:"AC-024-1",given:"a file of 500 valid instant payments",when:"the file is submitted",then:"each item is executed individually and a per-item outcome report is available within 10 minutes"}],relatedDocuments:["DOC-006"],relatedApis:[],relatedTestCases:[],relatedRules:["BR-005"]}];function i(e){return n.find(t=>t.id===e)}let s=Array.from(new Set(n.map(e=>e.category))).sort()},9535:(e,t,a)=>{a.d(t,{Sy:()=>i,WB:()=>n});let n=[{id:"TC-001",scenario:"Successful instant payment to a reachable beneficiary",suite:"Payment Initiation",preconditions:["Retail customer authenticated in the mobile app","Current account NL91NRTB0417164300 with an available balance of EUR 5,000","Beneficiary bank present in the TIPS reachability directory"],steps:[{step:1,action:"Enter beneficiary IBAN DE89370400440532013000 and name Helena Brandt",expected:"Verification of Payee returns MATCH and the instant badge is displayed"},{step:2,action:"Enter amount EUR 250.00 and confirm",expected:"SCA challenge is presented showing the exact amount and payee"},{step:3,action:"Complete biometric authentication",expected:"Payment is settled and status ACCP with a scheme reference is displayed within 10 seconds"}],expectedResult:"Payment settles at TIPS, the account is debited once and the confirmation shows the scheme reference and updated balance.",status:"Passed",priority:"Critical",type:"Functional",linkedRequirement:"REQ-001",lastRun:"2025-05-14",executedBy:"Sofia Marchetti"},{id:"TC-002",scenario:"Remittance information exceeding 140 characters is rejected",suite:"Payment Initiation",preconditions:["Authenticated retail customer","Valid beneficiary details captured"],steps:[{step:1,action:"Enter a 141-character remittance reference",expected:"The channel prevents further input at 140 characters"},{step:2,action:"Submit the request directly to the API with 141 characters",expected:"HTTP 400 with error code IPH-VAL-014"},{step:3,action:"Query the ledger for reservations",expected:"No funds reservation was created"}],expectedResult:"Payment is rejected at validation with IPH-VAL-014 and no downstream call is made.",status:"Passed",priority:"Medium",type:"Negative",linkedRequirement:"REQ-001",lastRun:"2025-05-14",executedBy:"Sofia Marchetti"},{id:"TC-003",scenario:"Duplicate submission with the same idempotency key returns the original payment",suite:"Payment Initiation",preconditions:["A payment already settled with idempotency key idem-8842011-20250602"],steps:[{step:1,action:"Resubmit the identical request with the same idempotency key",expected:"HTTP 201 returning the original paymentId"},{step:2,action:"Query PAYMENT_INSTRUCTION for the end-to-end identification",expected:"Exactly one row exists"}],expectedResult:"No second payment is created and the customer is not debited twice.",status:"Passed",priority:"Critical",type:"Regression",linkedRequirement:"REQ-001",lastRun:"2025-05-14",executedBy:"Sofia Marchetti"},{id:"TC-004",scenario:"Verification of Payee returns CLOSE_MATCH and the customer confirms",suite:"Verification of Payee",preconditions:["Beneficiary registered as H. M. Brandt at the beneficiary bank"],steps:[{step:1,action:"Enter the beneficiary name Helena Brandt",expected:"CLOSE_MATCH is returned with the registered name H. M. Brandt"},{step:2,action:"Select Continue with this name",expected:"The confirmation is recorded and the payment proceeds"},{step:3,action:"Inspect the audit record",expected:"The match score and the customer decision are persisted"}],expectedResult:"Payment proceeds only after an explicit confirmation, which is retained in the audit trail.",status:"Passed",priority:"High",type:"Functional",linkedRequirement:"REQ-002",lastRun:"2025-05-12",executedBy:"Hannah Okafor"},{id:"TC-005",scenario:"Verification of Payee NO_MATCH blocks a first-use beneficiary",suite:"Verification of Payee",preconditions:["Beneficiary has never been paid by this customer"],steps:[{step:1,action:"Enter a beneficiary name that does not match the account records",expected:"NO_MATCH is returned"},{step:2,action:"Attempt to continue",expected:"Submission is blocked with IPH-VOP-022 and a scam warning is displayed"}],expectedResult:"The payment cannot be submitted and the customer is directed to verify the details with the payee.",status:"Passed",priority:"High",type:"Negative",linkedRequirement:"REQ-002",lastRun:"2025-05-12",executedBy:"Hannah Okafor"},{id:"TC-006",scenario:"Verification of Payee service unavailable — risk acceptance path",suite:"Verification of Payee",preconditions:["VoP service stubbed to return HTTP 504"],steps:[{step:1,action:"Enter valid beneficiary details",expected:"The channel warns that verification could not be performed"},{step:2,action:"Accept the risk and continue",expected:"The acceptance is recorded and the payment proceeds"}],expectedResult:"Degraded mode allows the payment only with an explicit, audited risk acceptance.",status:"Passed",priority:"Medium",type:"Functional",linkedRequirement:"REQ-002",lastRun:"2025-05-12",executedBy:"Hannah Okafor"},{id:"TC-007",scenario:"Sanctions hit places the payment in a compliance hold",suite:"Financial Crime",preconditions:["Test beneficiary name seeded on the internal watch list"],steps:[{step:1,action:"Submit a payment to the listed beneficiary",expected:"HTTP 202 with a neutral 'completing some checks' message"},{step:2,action:"Inspect the compliance hold queue",expected:"An alert is raised within 5 seconds with the payment attached"},{step:3,action:"Inspect the customer channel and the agent desktop",expected:"Neither discloses that screening occurred"}],expectedResult:"Payment is held, funds remain reserved and no tip-off occurs.",status:"Passed",priority:"Critical",type:"Functional",linkedRequirement:"REQ-003",lastRun:"2025-05-13",executedBy:"Tobias Lindqvist"},{id:"TC-008",scenario:"Screening timeout routes the payment to manual review, never auto-approve",suite:"Financial Crime",preconditions:["Screening platform stubbed to respond after 1,500 ms"],steps:[{step:1,action:"Submit a payment",expected:"The circuit breaker triggers at 1,200 ms"},{step:2,action:"Check the payment status",expected:"Status is HELD, routed to manual review"}],expectedResult:"A screening timeout never results in automatic approval.",status:"Passed",priority:"Critical",type:"Negative",linkedRequirement:"REQ-003",lastRun:"2025-05-13",executedBy:"Tobias Lindqvist"},{id:"TC-009",scenario:"Fraud score of 72 triggers step-up authentication",suite:"Financial Crime",preconditions:["Fraud engine stubbed to return a score of 72"],steps:[{step:1,action:"Submit a payment of EUR 3,000",expected:"A step-up authentication challenge is presented"},{step:2,action:"Complete the challenge successfully",expected:"The payment continues and settles"}],expectedResult:"Medium-risk payments are challenged rather than blocked.",status:"Passed",priority:"High",type:"Functional",linkedRequirement:"REQ-004",lastRun:"2025-05-13",executedBy:"Tobias Lindqvist"},{id:"TC-010",scenario:"Fraud score of 91 blocks the payment and creates a case",suite:"Financial Crime",preconditions:["Fraud engine stubbed to return a score of 91"],steps:[{step:1,action:"Submit a payment of EUR 8,000",expected:"HTTP 403 with IPH-FRD-031"},{step:2,action:"Inspect the fraud review queue",expected:"A case exists with the score, model version and rule identifier"}],expectedResult:"High-risk payments are blocked and referred to Fraud Operations with full decision evidence.",status:"Passed",priority:"Critical",type:"Negative",linkedRequirement:"REQ-004",lastRun:"2025-05-13",executedBy:"Tobias Lindqvist"},{id:"TC-011",scenario:"Fraud engine unavailable — static fallback rules apply",suite:"Financial Crime",preconditions:["Fraud engine stubbed to return HTTP 503"],steps:[{step:1,action:"Submit a payment of EUR 2,500 to a first-use beneficiary",expected:"Step-up authentication is requested under the fallback rules"},{step:2,action:"Submit a payment of EUR 50 to an established beneficiary",expected:"The payment proceeds without a challenge"}],expectedResult:"Degraded mode applies conservative static rules rather than failing open or closed entirely.",status:"Passed",priority:"High",type:"Integration",linkedRequirement:"REQ-004",lastRun:"2025-05-13",executedBy:"Tobias Lindqvist"},{id:"TC-012",scenario:"Reservation converts to a booked debit on scheme acceptance",suite:"Ledger & Settlement",preconditions:["Account with an available balance of EUR 5,000"],steps:[{step:1,action:"Submit a payment of EUR 1,250 and observe the balance during processing",expected:"Available balance drops by EUR 1,250 while the ledger balance is unchanged"},{step:2,action:"Wait for scheme acceptance",expected:"The reservation converts to a booked debit carrying the scheme reference"}],expectedResult:"Funds are secured before submission and booked exactly once on acceptance.",status:"Passed",priority:"Critical",type:"Integration",linkedRequirement:"REQ-005",lastRun:"2025-05-09",executedBy:"Priya Raghunathan"},{id:"TC-013",scenario:"Reservation is released when no scheme response is received",suite:"Ledger & Settlement",preconditions:["TIPS gateway stubbed to never respond"],steps:[{step:1,action:"Submit a payment of EUR 900",expected:"Reservation is created"},{step:2,action:"Wait 25 seconds",expected:"The reservation is released and the payment is rejected with reason TIMEOUT"},{step:3,action:"Check the available balance",expected:"The full EUR 900 is restored"}],expectedResult:"Customer funds are never trapped by an unanswered scheme submission.",status:"Passed",priority:"Critical",type:"Negative",linkedRequirement:"REQ-005",lastRun:"2025-05-09",executedBy:"Priya Raghunathan"},{id:"TC-014",scenario:"pacs.008 construction and pacs.002 correlation",suite:"Scheme Messaging",preconditions:["Scheme simulator connected"],steps:[{step:1,action:"Submit a valid payment",expected:"A schema-valid pacs.008.001.08 is produced"},{step:2,action:"Return a pacs.002 with the matching end-to-end identification",expected:"The response is correlated and persisted against the payment"}],expectedResult:"Scheme messages are schema-valid and correctly correlated.",status:"Passed",priority:"Critical",type:"Integration",linkedRequirement:"REQ-006",lastRun:"2025-05-08",executedBy:"Priya Raghunathan"},{id:"TC-015",scenario:"Uncorrelated scheme response is quarantined",suite:"Scheme Messaging",preconditions:["Scheme simulator configured to return an unknown end-to-end identification"],steps:[{step:1,action:"Trigger the unmatched pacs.002",expected:"The message is quarantined with IPH-SCH-062"},{step:2,action:"Check the operations queue",expected:"An investigation item is created within 30 minutes"}],expectedResult:"Unmatched scheme messages never mutate an existing payment.",status:"Passed",priority:"High",type:"Negative",linkedRequirement:"REQ-006",lastRun:"2025-05-08",executedBy:"Priya Raghunathan"},{id:"TC-016",scenario:"Scheme rejection AC04 is translated for the customer",suite:"Exception Handling",preconditions:["Scheme simulator returns pacs.002 RJCT with reason AC04"],steps:[{step:1,action:"Submit a payment",expected:"Status becomes RJCT"},{step:2,action:"Read the channel message",expected:"'The beneficiary account is closed' is displayed, not the raw code"},{step:3,action:"Check the balance",expected:"The reservation has been released"}],expectedResult:"Scheme reason codes are translated into plain language and funds are returned.",status:"Passed",priority:"High",type:"Functional",linkedRequirement:"REQ-007",lastRun:"2025-05-08",executedBy:"Sofia Marchetti"},{id:"TC-017",scenario:"Late scheme acceptance after timeout creates an exception record",suite:"Exception Handling",preconditions:["Scheme simulator responds ACCP after 30 seconds"],steps:[{step:1,action:"Submit a payment and allow it to time out",expected:"Payment is rejected and the reservation released"},{step:2,action:"Allow the late ACCP to arrive",expected:"A LATE_ACCEPT exception record is created and the debit is posted"},{step:3,action:"Check the operations queue",expected:"The case is assigned for same-day customer contact"}],expectedResult:"Late acceptances are handled deterministically without mutating the terminal state.",status:"Failed",priority:"High",type:"Negative",linkedRequirement:"REQ-007",lastRun:"2025-05-16",executedBy:"Sofia Marchetti",defect:"DEF-1207"},{id:"TC-018",scenario:"Inbound instant payment is credited immediately",suite:"Inbound Payments",preconditions:["Active beneficiary current account"],steps:[{step:1,action:"Inject an inbound pacs.008 of EUR 1,200",expected:"The account is credited with immediate availability"},{step:2,action:"Check the response to the scheme",expected:"A positive pacs.002 is returned within 5 seconds"}],expectedResult:"Inbound funds are available immediately with no value-dating.",status:"Passed",priority:"Critical",type:"Functional",linkedRequirement:"REQ-008",lastRun:"2025-05-07",executedBy:"Priya Raghunathan"},{id:"TC-019",scenario:"Inbound payment to a closed account is rejected with AC04",suite:"Inbound Payments",preconditions:["Beneficiary account in CLOSED status"],steps:[{step:1,action:"Inject an inbound pacs.008",expected:"A negative pacs.002 with reason AC04 is returned"},{step:2,action:"Check the ledger",expected:"No credit is posted"}],expectedResult:"Inbound payments to invalid accounts are rejected using the correct scheme reason code.",status:"Passed",priority:"High",type:"Negative",linkedRequirement:"REQ-008",lastRun:"2025-05-07",executedBy:"Priya Raghunathan"},{id:"TC-020",scenario:"Inbound payment with a sanctions hit is held",suite:"Inbound Payments",preconditions:["Sender name seeded on the watch list"],steps:[{step:1,action:"Inject the inbound payment",expected:"The credit is withheld and a compliance alert is raised"},{step:2,action:"Check the beneficiary balance",expected:"The balance is unchanged and no notification is sent"}],expectedResult:"Inbound screening prevents crediting until compliance adjudication is complete.",status:"Passed",priority:"Critical",type:"Functional",linkedRequirement:"REQ-008",lastRun:"2025-05-07",executedBy:"Tobias Lindqvist"},{id:"TC-021",scenario:"Unreachable beneficiary bank is detected before confirmation",suite:"Reachability",preconditions:["Beneficiary BIC absent from the reachability directory"],steps:[{step:1,action:"Enter the beneficiary IBAN",expected:"The channel states that instant payment is unavailable for this bank"},{step:2,action:"Observe the offered alternative",expected:"Standard SCT is offered with the next value date"}],expectedResult:"Customers learn about unreachability before authorising, not after a rejection.",status:"Passed",priority:"High",type:"Functional",linkedRequirement:"REQ-009",lastRun:"2025-05-06",executedBy:"Hannah Okafor"},{id:"TC-022",scenario:"Reachability directory refresh is picked up without a restart",suite:"Reachability",preconditions:["Directory file updated with a newly reachable BIC"],steps:[{step:1,action:"Publish the updated directory",expected:"The hub reloads within 5 minutes"},{step:2,action:"Enter an IBAN for the newly reachable bank",expected:"The instant badge is displayed"}],expectedResult:"Daily directory updates take effect without downtime.",status:"Passed",priority:"Medium",type:"Integration",linkedRequirement:"REQ-009",lastRun:"2025-05-06",executedBy:"Priya Raghunathan"},{id:"TC-023",scenario:"Payment exceeding the remaining daily allowance is rejected",suite:"Limits",preconditions:["Retail customer with a EUR 15,000 daily limit and EUR 14,500 already sent"],steps:[{step:1,action:"Submit a payment of EUR 800",expected:"HTTP 422 with IPH-LIM-002"},{step:2,action:"Read the channel message",expected:"The remaining allowance of EUR 500 is displayed"}],expectedResult:"Limit rejections are precise and explain the remaining allowance.",status:"Passed",priority:"High",type:"Negative",linkedRequirement:"REQ-010",lastRun:"2025-05-05",executedBy:"Sofia Marchetti"},{id:"TC-024",scenario:"Cancelled payment restores the daily allowance",suite:"Limits",preconditions:["A payment of EUR 6,000 held in the cooling-off window"],steps:[{step:1,action:"Check the remaining allowance",expected:"The allowance is reduced by EUR 6,000"},{step:2,action:"Cancel the payment",expected:"The allowance is restored immediately"}],expectedResult:"Only payments in ACCP or PDNG consume the customer's allowance.",status:"Passed",priority:"Medium",type:"Functional",linkedRequirement:"REQ-010",lastRun:"2025-05-05",executedBy:"Sofia Marchetti"},{id:"TC-025",scenario:"Payment above the EUR 100,000 scheme cap is rejected at validation",suite:"Limits",preconditions:["SME customer with sufficient balance"],steps:[{step:1,action:"Submit a payment of EUR 100,000.01",expected:"HTTP 400 with IPH-VAL-001 within 300 ms"},{step:2,action:"Inspect the downstream service logs",expected:"No VoP, fraud, screening or ledger call was made"}],expectedResult:"The scheme cap is enforced before any downstream cost is incurred.",status:"Passed",priority:"Critical",type:"Negative",linkedRequirement:"REQ-011",lastRun:"2025-05-05",executedBy:"Sofia Marchetti"},{id:"TC-026",scenario:"Payment of exactly EUR 100,000.00 is accepted",suite:"Limits",preconditions:["SME customer with a sufficient limit and balance"],steps:[{step:1,action:"Submit a payment of EUR 100,000.00",expected:"The payment passes validation"},{step:2,action:"Wait for the outcome",expected:"The payment settles normally"}],expectedResult:"The boundary value is inclusive of the scheme maximum.",status:"Passed",priority:"High",type:"Functional",linkedRequirement:"REQ-011",lastRun:"2025-05-05",executedBy:"Sofia Marchetti"},{id:"TC-027",scenario:"Status enquiry returns the full stage history",suite:"Servicing",preconditions:["A settled payment exists"],steps:[{step:1,action:"Call GET /payments/{paymentId}",expected:"HTTP 200 with status ACCP and the scheme reference"},{step:2,action:"Inspect the statusHistory array",expected:"All transitions from RCVD to ACCP are present with timestamps"}],expectedResult:"The status enquiry is authoritative and complete for first-contact resolution.",status:"Passed",priority:"Medium",type:"Functional",linkedRequirement:"REQ-012",lastRun:"2025-05-12",executedBy:"Sofia Marchetti"},{id:"TC-028",scenario:"Reconciliation break is raised for a payment missing from the scheme statement",suite:"Reconciliation",preconditions:["camt.053 seeded without one settled payment"],steps:[{step:1,action:"Run the daily reconciliation",expected:"A break of type MISSING_AT_SCHEME is created"},{step:2,action:"Check the exception report",expected:"The break appears in the 07:00 CET report"}],expectedResult:"Settlement differences are detected and reported the same banking day.",status:"Passed",priority:"High",type:"Integration",linkedRequirement:"REQ-012",lastRun:"2025-05-16",executedBy:"Marcus Delacroix"},{id:"TC-029",scenario:"Recall raised within the scheme window is submitted",suite:"Recalls",preconditions:["Payment settled 3 banking days ago","Two authorised operations users available"],steps:[{step:1,action:"Raise a recall with reason code FRAD",expected:"The case is created in PENDING_APPROVAL"},{step:2,action:"Approve as a second authoriser",expected:"camt.056 is submitted and a 10 banking day clock starts"}],expectedResult:"Recalls follow the four-eyes process and are submitted to the scheme correctly.",status:"Passed",priority:"High",type:"Functional",linkedRequirement:"REQ-013",lastRun:"2025-05-15",executedBy:"Marcus Delacroix"},{id:"TC-030",scenario:"Recall outside the 10 banking day window is rejected",suite:"Recalls",preconditions:["Payment settled 12 banking days ago"],steps:[{step:1,action:"Attempt to raise a recall",expected:"HTTP 422 with IPH-RCL-003"},{step:2,action:"Read the guidance shown",expected:"The user is directed to the bilateral claim process"}],expectedResult:"The scheme window is enforced on the TARGET2 calendar.",status:"Passed",priority:"Medium",type:"Negative",linkedRequirement:"REQ-013",lastRun:"2025-05-15",executedBy:"Marcus Delacroix"},{id:"TC-031",scenario:"Inbound recall with funds available is returned in full",suite:"Recalls",preconditions:["Inbound payment of EUR 2,000 credited, funds still available"],steps:[{step:1,action:"Inject a camt.056 recall request",expected:"A hold is placed on EUR 2,000 and a case is created"},{step:2,action:"Approve the return with four-eyes",expected:"camt.029 acceptance is sent and the funds are returned same day"}],expectedResult:"Inbound recalls are answered within the scheme deadline with the correct message.",status:"Passed",priority:"High",type:"Functional",linkedRequirement:"REQ-014",lastRun:"2025-05-15",executedBy:"Marcus Delacroix"},{id:"TC-032",scenario:"Inbound recall with partially spent funds returns the recovered amount",suite:"Recalls",preconditions:["Inbound payment of EUR 2,000 credited, EUR 200 remaining"],steps:[{step:1,action:"Inject the recall request",expected:"The available EUR 200 is held"},{step:2,action:"Approve a partial return",expected:"camt.029 reports a partial return of EUR 200 and the case records the shortfall"}],expectedResult:"Partial recovery is supported and accurately reported to the requesting bank.",status:"Passed",priority:"Medium",type:"Functional",linkedRequirement:"REQ-014",lastRun:"2025-05-15",executedBy:"Marcus Delacroix"},{id:"TC-033",scenario:"Push notification is delivered for an inbound credit",suite:"Notifications",preconditions:["Customer with push notifications enabled"],steps:[{step:1,action:"Inject an inbound payment of EUR 1,200",expected:"A push notification is delivered within 30 seconds"},{step:2,action:"Read the notification content",expected:"It shows the amount, the sender name and the new balance"}],expectedResult:"Customers are informed immediately of received instant payments.",status:"Passed",priority:"Medium",type:"Integration",linkedRequirement:"REQ-015",lastRun:"2025-05-13",executedBy:"Hannah Okafor"},{id:"TC-034",scenario:"Quiet hours suppress non-urgent notifications",suite:"Notifications",preconditions:["Customer quiet hours set from 22:00 to 07:00"],steps:[{step:1,action:"Trigger a marketing-classified payment message at 23:00",expected:"Delivery is deferred to 07:00"},{step:2,action:"Trigger a settled payment confirmation at 23:00",expected:"It is delivered immediately as a transactional message"}],expectedResult:"Transactional notifications always bypass quiet hours.",status:"Blocked",priority:"Low",type:"Functional",linkedRequirement:"REQ-015",lastRun:"2025-05-14",executedBy:"Hannah Okafor",defect:"DEF-1198"},{id:"TC-035",scenario:"One-click fallback to standard SCT retains all payment details",suite:"Payment Initiation",preconditions:["Beneficiary bank unreachable for instant payments"],steps:[{step:1,action:"Accept the standard SCT fallback offer",expected:"A standard transfer is pre-populated with the same details"},{step:2,action:"Confirm the transfer",expected:"The next available value date is confirmed"}],expectedResult:"Customers complete their payment without re-keying any details.",status:"Passed",priority:"Medium",type:"Functional",linkedRequirement:"REQ-016",lastRun:"2025-05-06",executedBy:"Hannah Okafor"},{id:"TC-036",scenario:"SCA challenge is dynamically linked to amount and payee",suite:"Security",preconditions:["Authenticated customer, new beneficiary, amount EUR 4,000"],steps:[{step:1,action:"Confirm the payment",expected:"The challenge displays EUR 4,000 and the beneficiary name"},{step:2,action:"Amend the amount to EUR 4,500 before authenticating",expected:"The original challenge is invalidated and a new one is issued"}],expectedResult:"Dynamic linking is enforced for every material change.",status:"Passed",priority:"Critical",type:"Functional",linkedRequirement:"REQ-017",lastRun:"2025-05-10",executedBy:"Tobias Lindqvist"},{id:"TC-037",scenario:"Low-value SCA exemption applies and is audited",suite:"Security",preconditions:["Trusted beneficiary registered, cumulative exempt amount at EUR 300"],steps:[{step:1,action:"Submit a payment of EUR 40",expected:"No challenge is raised"},{step:2,action:"Inspect the audit record",expected:"EXEMPT_LOW_VALUE is recorded with the cumulative counter"},{step:3,action:"Submit further payments until the cumulative exempt amount exceeds EUR 1,000",expected:"SCA is enforced on the payment that breaches the threshold"}],expectedResult:"Exemptions are applied within the RTS thresholds and are fully auditable.",status:"Passed",priority:"High",type:"Functional",linkedRequirement:"REQ-017",lastRun:"2025-05-10",executedBy:"Tobias Lindqvist"},{id:"TC-038",scenario:"Cooling-off hold applies to a first payment above EUR 5,000",suite:"Financial Crime",preconditions:["Beneficiary added 10 minutes ago"],steps:[{step:1,action:"Submit a payment of EUR 7,500",expected:"The payment is held for 30 minutes and shown as cancellable"},{step:2,action:"Wait for the hold to expire",expected:"The payment resumes automatically and settles"}],expectedResult:"New-beneficiary risk is mitigated without permanently blocking genuine payments.",status:"Passed",priority:"High",type:"Functional",linkedRequirement:"REQ-018",lastRun:"2025-05-11",executedBy:"Tobias Lindqvist"},{id:"TC-039",scenario:"Sustained peak load of 120 TPS with zero-downtime deployment",suite:"Performance",preconditions:["Performance environment sized to production","Rolling deployment prepared"],steps:[{step:1,action:"Apply 120 TPS for 60 minutes",expected:"95th percentile response time remains at or below 5,000 ms"},{step:2,action:"Execute a rolling deployment mid-test",expected:"No inbound scheme payment fails or times out"},{step:3,action:"Review the availability measurement",expected:"Availability remains at or above 99.9%"}],expectedResult:"The hub sustains peak load and remains reachable through deployments.",status:"Passed",priority:"Critical",type:"Performance",linkedRequirement:"REQ-020",lastRun:"2025-05-16",executedBy:"Priya Raghunathan"}],i=Array.from(new Set(n.map(e=>e.suite))).sort()}}]);